# Tree forms generated by L-systems (wikibio.botany.lsystem_tree): excurrent monopodial crown (Picea,
# Abies), fastigiate (Populus nigra 'Italica'), weeping (Salix babylonica), sympodial Leeuwenberg model
# (Plumeria), repeated dichotomy (early land plants) and the unbranched palm (Corner's model).
import wikibio as bio
from wikibio import botany as B

P = bio.P
fig, ax = bio.canvas(36.0, 10.0)
ax.plot([0.3, 35.7], [0.9, 0.9], color=P.edge("animal"), lw=1.0)
habits = [("excurrent", "Excurrent"), ("fastigiate", "Fastigiate"), ("weeping", "Weeping"), ("leeuwenberg", "Sympodial"),
          ("dichotomous", "Dichotomous"), ("palm", "Unbranched (palm)")]
for k, (h, name) in enumerate(habits):
    x = 3.0 + k * 6.0
    B.lsystem_tree(ax, (x, 0.9), 8.0, habit=h, width=5.0, seed=k)
    bio.label(ax, (x, 0.35), name, size="small")
